  {
   "$ref": "#/$defs/RunFile"
  },
  {
   "$ref": "#/$defs/AnalysisFile"
  },
  {
   "$ref": "#/$defs/MetricFile"
  },
  {
   "$ref": "#/$defs/ResourceFile"
  },
  {
   "$ref": "#/$defs/DecisionFile"
  },
  {
   "$ref": "#/$defs/CriteriaFile"
  }
 ],
 "$defs": {
  "Acquisition": {
