       "maxLength": 600,
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "title": "Url"
    },
    "recipe": {
     "anyOf": [
      {
       "maxLength": 1000,
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "title": "Recipe"
    }
   },
   "title": "Acquisition",
   "type": "object"
  },
  "Agent": {
   "additionalProperties": true,
   "description": "The agent that made a write, as rb knew it then: its name (its runtime's, as its actor names it), the version its\nruntime or its MCP client gave, its provider and its model, each with where rb has it from. `provider_from` is\n`said` (rb context --provider, the context tool), `env` (RB_PROVIDER, for one command) or `inferred` (rb's table\nof runtimes); `model_from` is `said` (rb context --model, the context tool) or `env` (RB_MODEL, for one command).\nrb never guesses a model. A key a later rb adds is kept.",
   "properties": {
    "name": {
     "title": "Name",
     "type": "string"
    },
    "version": {
     "anyOf": [
      {
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "title": "Version"
    },
    "provider": {
     "anyOf": [
      {
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "title": "Provider"
    },
    "provider_from": {
     "anyOf": [
      {
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "title": "Provider From"
    },
    "model": {
     "anyOf": [
      {
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "title": "Model"
    },
    "model_from": {
     "anyOf": [
      {
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "title": "Model From"
    }
   },
   "required": [
    "name"
   ],
   "title": "Agent",
   "type": "object"
  },
  "Amendment": {
   "additionalProperties": false,
   "properties": {
    "at": {
     "title": "At",
     "type": "string"
    },
    "by": {
     "pattern": "^(human|agent):[A-Za-z0-9_.@+-]{1,80}$",
     "title": "By",
     "type": "string"
    },
    "why": {
     "maxLength": 1000,
     "minLength": 1,
     "title": "Why",
     "type": "string"
    },
