   "title": "ConfigCheck",
   "type": "object"
  },
  "Conflict": {
   "additionalProperties": false,
   "description": "A verified source that now states a different value. Re-verifying never clears it: the setting's value or its\nsource has to change.",
   "properties": {
    "at": {
     "title": "At",
     "type": "string"
    },
    "read": {
     "default": null,
